package io.github.jesterportfolio.hearth.story;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class StoryRuntimeSettingsTest {
    static Map<String,Object> run(){var m=new HashMap<String,Object>();m.put("run",new UUID(12,1).toString());m.put("world-key","hearth_story:one");m.put("world-uuid",new UUID(13,1).toString());m.put("template-version","v1");m.put("template-sha256","a".repeat(64));m.put("entry-x",5.5);m.put("entry-y",64);m.put("entry-z",5.5);m.put("entry-yaw",0);m.put("entry-pitch",0);m.put("required-regions",List.of("protected"));return m;}
    static Map<String,Object> settings(){var m=new HashMap<String,Object>();m.put("runs",List.of(run()));m.put("members",List.of(Map.of("player",new UUID(14,1).toString(),"run",new UUID(12,1).toString())));m.put("content-file","story.yml");m.put("content-sha256","b".repeat(64));m.put("idle-seconds",30);m.put("capacity",4);m.put("db-host","127.0.0.1");m.put("db-port",5432);m.put("db-name","hearth_story");m.put("db-user","hearth");m.put("password-environment","HEARTH_DB_PASSWORD");return m;}
    @Test void explicitConfigurationIsImmutableAndHasNoSecret(){var s=StoryRuntimeSettings.parse(settings());assertEquals(4,s.capacity());assertEquals("HEARTH_DB_PASSWORD",s.passwordEnvironment());assertThrows(UnsupportedOperationException.class,()->s.runs().clear());assertThrows(UnsupportedOperationException.class,()->s.members().clear());assertThrows(UnsupportedOperationException.class,()->s.runs().values().iterator().next().regions().clear());}
    @Test void missingSettingsCannotDefaultToFixtureOrExistingPrimaryWorld(){for(String k:settings().keySet()){var m=settings();m.remove(k);assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m),k);}for(String k:run().keySet()){var m=settings();var r=run();r.remove(k);m.put("runs",List.of(r));assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m),k);}}
    @Test void duplicateRunPhysicalIdentityOrMembershipRejected(){for(String k:List.of("run","world-key","world-uuid")){var m=settings();var r=run();r.put("run",new UUID(12,2).toString());r.put("world-key","hearth_story:two");r.put("world-uuid",new UUID(13,2).toString());r.put(k,run().get(k));m.put("runs",List.of(run(),r));assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m),k);}var m=settings();m.put("members",List.of(Map.of("player",new UUID(14,1).toString(),"run",new UUID(12,1).toString()),Map.of("player",new UUID(14,1).toString(),"run",new UUID(12,1).toString())));assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m));}
    @Test void unsupportedMembersUnsafePathsAndCoordinatesRejected(){for(var changes:List.of(Map.of("world-key","minecraft:overworld"),Map.of("world-key","hearth_story:../one"),Map.of("entry-x",Double.NaN),Map.of("entry-pitch",91),Map.of("required-regions",List.of()),Map.of("template-version","../v1"),Map.of("template-sha256","bad"))){var m=settings();var r=run();r.putAll(changes);m.put("runs",List.of(r));assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m));}var m=settings();m.put("members",List.of(Map.of("player",new UUID(14,1).toString(),"run",new UUID(12,2).toString())));assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m));}
    @Test void connectionInjectionFractionalLimitsAndContentAliasesRejected(){for(var changes:List.of(Map.of("content-file","../story.yml"),Map.of("content-sha256","bad"),Map.of("capacity",1.5),Map.of("capacity",0),Map.of("idle-seconds",3601),Map.of("db-host","host/password"),Map.of("db-port",65536),Map.of("password-environment","secret=value"))){var m=settings();m.putAll(changes);assertThrows(RuntimeException.class,()->StoryRuntimeSettings.parse(m));}}
}
